// Generated by Tessa from plans/manage-roles/tests.json (run 20261016T080106Z).
// Story: Manage user roles
// Sessions come from stored storage state files; see README.md. No credentials are in this file.
import { expect, test } from '@playwright/test';

test.describe('Manage user roles', () => {
  test.describe('as admin', () => {
    // Signed-in session for admin; see README.md.
    test.use({ storageState: process.env.TESSA_AUTH_ADMIN ?? '.auth/admin.json' });

    test(
      'Admin promotes a viewer to editor',
      {
        tag: ['@manage-roles', '@admin', '@happy-path'],
        annotation: [
          {
            type: 'intent',
            description:
              "Proves an admin can change another user's role and the change is saved, not just shown.",
          },
          { type: 'seed-profile', description: 'admin-heavy' },
          { type: 'criterion', description: 'ac-1' },
        ],
      },
      async ({ page }) => {
        await page.goto('/admin/users');
        await test.step("Set the viewer's role to editor", async () => {
          await page.getByTestId('role-select-viewer').selectOption('editor');
        });
        await test.step("Save the viewer's role", async () => {
          await page.getByTestId('role-save-viewer').click();
        });
        await test.step('Reload the Users page', async () => {
          await page.goto('/admin/users');
        });
        await test.step("The viewer's role is now editor", async () => {
          await expect(page.getByTestId('role-select-viewer')).toHaveValue('editor');
        });
      },
    );

    test(
      'Admin cannot change their own role',
      {
        tag: ['@manage-roles', '@admin', '@edge'],
        annotation: [
          {
            type: 'intent',
            description:
              "Proves the signed-in admin's own row cannot be edited, so an admin cannot demote themselves.",
          },
          { type: 'seed-profile', description: 'admin-heavy' },
          { type: 'criterion', description: 'ac-2' },
        ],
      },
      async ({ page }) => {
        await page.goto('/admin/users');
        await test.step("The admin's own role select is disabled", async () => {
          await expect(page.getByTestId('role-select-admin')).toBeDisabled();
        });
        await test.step("The admin's own Save button is disabled", async () => {
          await expect(page.getByTestId('role-save-admin')).toBeDisabled();
        });
        await test.step("Another admin's role can still be edited", async () => {
          await expect(page.getByTestId('role-select-admin2')).toBeEnabled();
        });
      },
    );
  });

  test.describe('as editor', () => {
    // Signed-in session for editor; see README.md.
    test.use({ storageState: process.env.TESSA_AUTH_EDITOR ?? '.auth/editor.json' });

    test(
      'Editor cannot reach the Users page',
      {
        tag: ['@manage-roles', '@editor', '@permissions'],
        annotation: [
          {
            type: 'intent',
            description:
              'Proves the manage-users permission is enforced for editors in navigation and on the server.',
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-3' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets');
        await test.step('No Users link in the navigation', async () => {
          await expect(page.getByTestId('nav-admin-users')).toHaveCount(0);
        });
        await test.step('Go to the Users page directly', async () => {
          await page.goto('/admin/users');
        });
        await test.step('A permission error is shown', async () => {
          await expect(page.getByRole('alert')).toContainText('permission');
        });
      },
    );
  });

  test.describe('as viewer', () => {
    // Signed-in session for viewer; see README.md.
    test.use({ storageState: process.env.TESSA_AUTH_VIEWER ?? '.auth/viewer.json' });

    test(
      'Viewer cannot reach the Users page',
      {
        tag: ['@manage-roles', '@viewer', '@permissions'],
        annotation: [
          {
            type: 'intent',
            description:
              'Proves the manage-users permission is enforced for viewers in navigation and on the server.',
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-3' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets');
        await test.step('No Users link in the navigation', async () => {
          await expect(page.getByTestId('nav-admin-users')).toHaveCount(0);
        });
        await test.step('Go to the Users page directly', async () => {
          await page.goto('/admin/users');
        });
        await test.step('A permission error is shown', async () => {
          await expect(page.getByRole('alert')).toContainText('permission');
        });
      },
    );
  });
});
